mkdir -p /tmp/budget-test && cat > /tmp/budget-test/test.mjs <<'EOF'
import assert from 'node:assert/strict';
const W = 'file:///C:/Users/USER/Downloads/agent-test/limit/haiku_t4_r3/work/js/';
const { parseCSV, toCSV } = await import(W + 'csv.js');
const { summarize } = await import(W + 'summary.js');
const { expandRecurring } = await import(W + 'recurring.js');
const { checkBudgets } = await import(W + 'budget.js');
const { createHistory } = await import(W + 'history.js');

// csv
const text = 'date,description,amount,category\r\n2026-01-02,"Coffee, large",-3.5,food\n2026-01-03,"He said ""hi""\r\nline two",100,"income"\n';
const rows = parseCSV(text);
assert.deepEqual(rows, [
  { date: '2026-01-02', description: 'Coffee, large', amount: -3.5, category: 'food' },
  { date: '2026-01-03', description: 'He said "hi"\r\nline two', amount: 100, category: 'income' },
]);
assert.deepEqual(parseCSV(toCSV(rows)), rows);
assert.equal(toCSV([]), 'date,description,amount,category\n');
console.log('csv ok');

// summary
const items = [
  { date: '2026-01-01', description: 'a', amount: 1000, category: 'salary' },
  { date: '2026-01-05', description: 'b', amount: -200.1, category: 'rent' },
  { date: '2026-02-05', description: 'c', amount: -50, category: 'food' },
  { date: '2026-02-06', description: 'd', amount: -0.2, category: 'food' },
];
const s = summarize(items);
assert.equal(s.income, 1000); assert.equal(s.expense, 250.3); assert.equal(s.balance, 749.7);
assert.deepEqual(s.byCategory, { salary: 1000, rent: -200.1, food: -50.2 });
const r = summarize(items, { from: '2026-02-01', to: '2026-02-05' });
assert.equal(r.expense, 50); assert.equal(r.income, 0); assert.deepEqual(r.byCategory, { food: -50 });
console.log('summary ok');

// recurring
const m = expandRecurring({ date: '2026-01-31', description: 'x', amount: -5, category: 'c', every: 'month' }, '2026-04-30');
assert.deepEqual(m.map(i => i.date), ['2026-01-31', '2026-02-28', '2026-03-31', '2026-04-30']);
assert.deepEqual(m[0], { date: '2026-01-31', description: 'x', amount: -5, category: 'c' });
const w = expandRecurring({ date: '2026-02-25', description: 'x', amount: -5, category: 'c', every: 'week' }, '2026-03-11');
assert.deepEqual(w.map(i => i.date), ['2026-02-25', '2026-03-04', '2026-03-11']);
assert.deepEqual(expandRecurring({ date: '2026-05-01', description: 'x', amount: 1, category: 'c', every: 'week' }, '2026-04-01'), []);
const leap = expandRecurring({ date: '2024-01-31', description: 'x', amount: 1, category: 'c', every: 'month' }, '2024-03-31');
assert.deepEqual(leap.map(i => i.date), ['2024-01-31', '2024-02-29', '2024-03-31']);
const y = expandRecurring({ date: '2025-12-15', description: 'x', amount: 1, category: 'c', every: 'month' }, '2026-02-15');
assert.deepEqual(y.map(i => i.date), ['2025-12-15', '2026-01-15', '2026-02-15']);
console.log('recurring ok');

// budget
const b = checkBudgets(items, [{ category: 'food', limit: 50 }, { category: 'rent', limit: 300 }, { category: 'travel', limit: 10 }], '2026-02');
assert.deepEqual(b, [
  { category: 'food', limit: 50, spent: 50.2, over: true },
  { category: 'rent', limit: 300, spent: 0, over: false },
  { category: 'travel', limit: 10, spent: 0, over: false },
]);
console.log('budget ok');

// history
const h = createHistory(['a']);
h.push(['a', 'b']); h.push(['a', 'b', 'c']);
assert.equal(h.undo().length, 2); assert.equal(h.canRedo(), true);
h.push(['x']); assert.equal(h.canRedo(), false); assert.deepEqual(h.state(), ['x']);
h.undo(); h.undo(); assert.equal(h.canUndo(), false); h.redo(); assert.deepEqual(h.state(), ['a', 'b']);
const big = createHistory(0);
for (let i = 1; i <= 80; i++) big.push(i);
let steps = 0; while (big.canUndo()) { big.undo(); steps++; }
assert.equal(steps, 50); assert.equal(big.state(), 30);
console.log('history ok');
EOF
